import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClassUtils_toClass_TriageGen0Test {





    @Test
    public void testToClass_ValidObjects() {
        Object[] input = new Object[]{"string", 123, 45.67};
        Class<?>[] expected = new Class<?>[]{String.class, Integer.class, Double.class};
        Class<?>[] result = ClassUtils.toClass(input);

        Assert.assertNotNull(result);
        Assert.assertEquals(expected.length, result.length);
        for (int i = 0; i < expected.length; i++) {
            Assert.assertEquals("Class at index " + i + " does not match", expected[i], result[i]);
        }
    }




}

