public class ClassUtils_toClass_TriageGen0Test {







    @Test
    public void testToClass_WithNullElements() {
        Object[] input = new Object[]{"string", null, 123};
        Class<?>[] expected = new Class<?>[]{String.class, null, Integer.class};
        Class<?>[] result = ClassUtils.toClass(input);

        Assert.assertNotNull(result);
        Assert.assertEquals(expected.length, result.length);
        Assert.assertEquals(expected[0], result[0]);
        Assert.assertNull("Class at index 1 should be null", result[1]);
        Assert.assertEquals(expected[2], result[2]);
    }


}

